		return;
	}
	if(ctx->df || !(ctx->is_structured)) {
		ctx->buf = malloc(req->len);
		if(!(ctx->buf)) {
			err("Could not allocate memory for request");
		}
		ctx->buflen = req->len;
	}
	if(expread(ctx, client)) {
		DEBUG("Read failed: %m");
