/**
 * Read a chunk of at most one tree block from the tree file containing
 * offset a. Blocks for which no file exists read as zeroes.
 *
 * @param client The client we're serving for
 * @param a The offset into the export where the chunk starts
 * @param buf A buffer to read into
 * @param len The size of the chunk, which must not cross a block boundary
 * @return 0 on success, nonzero on failure
 **/
static int treeexpread(CLIENT *client, off_t a, char *buf, size_t len) {
	off_t foffset;
	int fhandle;
	ssize_t retval;

	foffset = a % TREEPAGESIZE;
	fhandle = open_treefile(client->exportname, O_RDONLY,
				client->exportsize, a, &tree_lock);
	if(fhandle < 0) {
		if(errno == ENOENT) {
			/* the block was never written, so it reads as zeroes */
			memset(buf, 0, len);
			return 0;
		}
		return -1;
	}
	retval = pread(fhandle, buf, len, foffset);
	close(fhandle);
	if(retval < 0)
		return -1;
	if((size_t)retval < len) {
		/* the file is shorter than the block; the remainder reads
		 * as zeroes */
		memset(buf + retval, 0, len - retval);
	}
	return 0;
}
