static ssize_t treeexpwrite(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	int fhandle;
	off_t foffset;
	size_t maxbytes;
	ssize_t retval;

	foffset = a % TREEPAGESIZE;
	maxbytes = TREEPAGESIZE - foffset;
	if(len > maxbytes)
		len = maxbytes;
	fhandle = open_treefile(client->exportname, O_RDWR | O_CREAT, client->exportsize, a, &tree_lock);
	if(fhandle < 0)
		return -1;
	DEBUG("(TREEWRITE to %s offset %llu len %u fua %d), ", client->exportname, (unsigned long long)foffset, (unsigned int)len, fua);
	retval = pwrite(fhandle, buf, len, foffset);
	if(retval > 0) {
		if(client->server->flags & F_SYNC)
			fsync(fhandle);
		else if(fua)
			fdatasync(fhandle);
	}
	close(fhandle);
	return retval;
}

static int treeexpwrite_fully(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	ssize_t ret = 0;

	while(len > 0 && (ret = treeexpwrite(a, buf, len, client, fua)) > 0) {
		a += ret;
		buf += ret;
		len -= ret;
	}
	return (ret < 0 || len != 0);
}
```

