arguments.content:
/*
 * Tree files support.
 *
 * When an export is configured with the treefiles option, the exported
 * data is stored in a tree of small files rather than in one large file.
 * The tree is rooted at the directory named by the exportname, and every
 * TREEPAGESIZE-sized block of the export maps to exactly one file in the
 * tree. Since every directory holds at most TREEDIRSIZE entries, exports
 * with more than TREEDIRSIZE blocks use nested TREEXXXX directories, as
 * many levels deep as needed to hold all blocks.
 *
 * Block files and directories are created on demand when data is written
 * to them, and block files are removed again when the corresponding block
 * is marked as unused. Reading a block for which no file exists returns
 * zeroes. This is useful on filesystems that do not handle large files
 * well, such as fuse/ftpfs, davfs or other network filesystems.
 *
 * See nbd-server(5) for details.
 */
#include "lfs.h"

#include <assert.h>
#include <errno.h>
#include <fcntl.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#include "treefiles.h"

/** Room a constructed path needs beyond the length of the tree root:
 * per nesting level one "/TREEXXXX" and one "/FILEXXXX" at the leaf,
 * plus a byte for the trailing NUL. Six levels address 2^72 bytes worth
 * of blocks, which is far more than off_t can express. */
#define TREEPATH_EXTRA (7 * (sizeof("/TREEXXXX") - 1) + 1)

pthread_mutex_t tree_lock = PTHREAD_MUTEX_INITIALIZER;

/**
 * Compute the number of levels of TREEXXXX directories needed to store
 * all blocks of an export of the given size. A size that fits in
 * TREEDIRSIZE blocks needs no subdirectories at all.
 *
 * @param size total size of the export
 * @return the number of directory levels below the tree root
 **/
static int tree_levels(off_t size) {
	off_t blocks;
	off_t capacity;
	int levels;

	blocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	capacity = TREEDIRSIZE;
	levels = 0;
	while(capacity < blocks) {
		levels++;
		capacity *= TREEDIRSIZE;
	}
	return levels;
}

/**
 * Construct the path of the block file holding the data at a given
 * offset of a treefiles export. The path is appended to the tree root
 * directory already present in name.
 *
 * @param name buffer holding the name of the tree root directory,
 *        overwritten with the full path of the block file
 * @param lenmax the size of the name buffer
 * @param size total size of the export
 * @param pos offset into the export
 * @param ppos set to the offset into the block file where the data at
 *        pos lives
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	off_t block;
	off_t divisor;
	int levels;
	int used;
	int l;

	assert(name != NULL);
	assert(pos >= 0);
	assert(pos < size);

	block = pos / TREEPAGESIZE;
	*ppos = pos % TREEPAGESIZE;

	levels = tree_levels(size);
	divisor = 1;
	for(l = 0; l < levels; l++) {
		divisor *= TREEDIRSIZE;
	}

	used = strlen(name);
	for(l = levels; l >= 1; l--) {
		assert(used < lenmax);
		used += snprintf(name + used, lenmax - used, "/TREE%04X",
				(unsigned int)(block / divisor));
		block %= divisor;
		divisor /= TREEDIRSIZE;
	}
	assert(used < lenmax);
	used += snprintf(name + used, lenmax - used, "/FILE%04X",
			(unsigned int)block);
	assert(used < lenmax);
}

/**
 * Create all directories on a path, like mkdir -p. Existing directories
 * are silently skipped.
 *
 * @param path the directory path to create; may be modified, but is
 *        restored before returning
 **/
void mkdir_path(char *path) {
	char *p;

	p = path;
	while((p = strchr(p + 1, '/')) != NULL) {
		*p = '\0';
		mkdir(path, 0700);
		*p = '/';
	}
	mkdir(path, 0700);
}

/**
 * Open the block file holding the data at a given offset of a treefiles
 * export. When O_CREAT is part of the mode, any directories leading up
 * to the file are created as needed; without it, trying to open a block
 * that was never written fails with ENOENT.
 *
 * @param name the name of the tree root directory
 * @param mode open mode, as for open(2)
 * @param size total size of the export
 * @param pos offset into the export
 * @param mutex mutex protecting path construction and directory creation
 * @return a file descriptor, or -1 on error
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char *path;
	char *sep;
	int lenmax;
	int fd;
	off_t ppos;

	lenmax = strlen(name) + TREEPATH_EXTRA;
	path = malloc(lenmax);
	if(path == NULL) {
		return -1;
	}
	strcpy(path, name);

	pthread_mutex_lock(mutex);
	construct_path(path, lenmax, size, pos, &ppos);
	if(mode & O_CREAT) {
		sep = strrchr(path, '/');
		assert(sep != NULL);
		*sep = '\0';
		mkdir_path(path);
		*sep = '/';
	}
	fd = open(path, mode, 0600);
	pthread_mutex_unlock(mutex);

	free(path);
	return fd;
}

/**
 * Delete the block file holding the data at a given offset of a
 * treefiles export, if it exists. The block then reads as zeroes again.
 *
 * @param name the name of the tree root directory
 * @param size total size of the export
 * @param pos offset into the export
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	char *path;
	int lenmax;
	off_t ppos;

	lenmax = strlen(name) + TREEPATH_EXTRA;
	path = malloc(lenmax);
	if(path == NULL) {
		return;
	}
	strcpy(path, name);
	construct_path(path, lenmax, size, pos, &ppos);
	unlink(path);
	free(path);
}

