/**
 * Punch a hole in a treefiles export. Blocks fully covered by the hole
 * lose their backing file, so that they read as zeroes again; partially
 * covered blocks are zeroed for the covered part.
 *
 * @param req the request for which this is being processed
 * @param client the client for which we're processing this request
 **/
static int exptrim_treefiles(struct nbd_request* req, CLIENT* client) {
	off_t pos = req->from;
	off_t len = req->len;

	while(len > 0) {
		off_t foffset = pos % TREEPAGESIZE;
		off_t blen = TREEPAGESIZE - foffset;

		if(blen > len) {
			blen = len;
		}
		if(foffset == 0 && blen == TREEPAGESIZE) {
			delete_treefile(client->exportname,
					client->exportsize, pos);
		} else {
			static const char zeroes[TREEPAGESIZE];
			int fhandle;

			fhandle = open_treefile(client->exportname, O_RDWR,
					client->exportsize, pos, &tree_lock);
			if(fhandle >= 0) {
				if(pwrite(fhandle, zeroes, blen, foffset) < 0) {
					close(fhandle);
					return -1;
				}
				close(fhandle);
			} else if(errno != ENOENT) {
				/* a block without a backing file is all
				 * zeroes already */
				return -1;
			}
		}
		pos += blen;
		len -= blen;
	}
	DEBUG("Performed TRIM request on treefiles from %llu to %llu", (unsigned long long) req->from, (unsigned long long) req->len);
	return 0;
}

