int main(void) {
	char path[256];
	char root[] = "/tmp/nbd-tree.XXXXXX";
	char buf[TREEPAGESIZE];
	char zeros[TREEPAGESIZE];
	off_t ppos;
	int fd;
	off_t size = 8*1024*1024; // 2048 blocks -> one level of TREE dirs

	count_assert(mkdtemp(root) != NULL);

	/* single-block export: files live directly in the root */
	strcpy(path, root);
	construct_path(path, sizeof path, TREEPAGESIZE, 0, &ppos);
	count_assert(strcmp(path + strlen(root), "/FILE0000") == 0);
	count_assert(ppos == 0);

	strcpy(path, root);
	construct_path(path, sizeof path, TREEPAGESIZE, TREEPAGESIZE - 1, &ppos);
	count_assert(strcmp(path + strlen(root), "/FILE0000") == 0);
	count_assert(ppos == TREEPAGESIZE - 1);

	/* 1024 blocks still fit in the root directory */
	strcpy(path, root);
	construct_path(path, sizeof path, TREEDIRSIZE * TREEPAGESIZE, (TREEDIRSIZE - 1) * TREEPAGESIZE, &ppos);
	count_assert(strcmp(path + strlen(root), "/FILE03FF") == 0);

	/* 1025 blocks need one level of TREE directories */
	strcpy(path, root);
	construct_path(path, sizeof path, (TREEDIRSIZE + 1) * TREEPAGESIZE, TREEDIRSIZE * TREEPAGESIZE, &ppos);
	count_assert(strcmp(path + strlen(root), "/TREE0001/FILE0000") == 0);

	/* different offsets map to different places */
	strcpy(path, root);
	construct_path(path, sizeof path, size, 3 * TREEPAGESIZE + 7, &ppos);
	count_assert(strcmp(path + strlen(root), "/TREE0000/FILE0003") == 0);
	count_assert(ppos == 7);

	strcpy(path, root);
	construct_path(path, sizeof path, size, size - 1, &ppos);
	count_assert(strcmp(path + strlen(root), "/TREE0001/FILE07FF") == 0);
	count_assert(ppos == TREEPAGESIZE - 1);

	/* open_treefile creates directories and files on demand */
	memset(buf, 'A', sizeof buf);
	fd = open_treefile(root, O_RDWR | O_CREAT, size, (TREEDIRSIZE + 2) * TREEPAGESIZE + 5, &mutex);
	count_assert(fd >= 0);
	count_assert(write(fd, buf, sizeof buf) == TREEPAGESIZE);
	close(fd);

	strcpy(path, root);
	construct_path(path, sizeof path, size, (TREEDIRSIZE + 2) * TREEPAGESIZE + 5, &ppos);
	struct stat st;
